const base = "https://qa.msu.io"; const open = async (u) => { await page.goto(new URL(u, base).href, { waitUntil: 'domcontentloaded' }); await page.waitForTimeout(4000); };
const hrefs = async (k) => [...new Set(await page.locator(`a[href*="/navigator/${k}/"]`).evaluateAll((as) => as.map((a) => a.getAttribute('href'))))];
await open("https://qa.msu.io/navigator");
